package com.mealmate.notification; import org.springframework.kafka.annotation.*; import org.springframework.stereotype.*; import java.util.*; @Component class NotificationConsumer{final NotificationRepository r;NotificationConsumer(NotificationRepository x){r=x;}@KafkaListener(topics={"food-order-events","payment-events","delivery-events"},groupId="notification-service")void on(Event e){if(r.existsByEventId(e.eventId()))return;r.save(new Notification(e.orderId(),e.type(),"Order "+e.type().toLowerCase(),e.eventId()));}record Event(String eventId,String type,UUID orderId,boolean failPayment,boolean failDeliveryAssignment){}}
